do $patch$ declare d text; begin select pg_get_functiondef('public.be_approved_tariff_lookup_key(text)'::regprocedure) into d; if strpos(d,'lower(btrim(p_value))')=0 then raise exception 'Unexpected tariff lookup'; end if; d:=replace(d,'lower(btrim(p_value))','regexp_replace(lower(btrim(p_value)), ''[[:space:]]*(township|မြို့နယ်)$'', '''', ''i'')'); d:=replace(d,'with aliases(alias,key) as (values ', 'with aliases(alias,key) as (values (''မင်္ဂလာတောင်ညွန့်'',''မင်္ဂလာတောင်ညွန့်''),(''mingalataungnyunt'',''မင်္ဂလာတောင်ညွန့်''),(''မင်္ဂလာတောင်ညွန့်'',''မင်္ဂလာတောင်ညွန့်''),(''ကြည့်မြင်တိုင်'',''ကြည့်မြင်တိုင်''),(''kyeemyindaing'',''ကြည့်မြင်တိုင်''),(''kyimyindine'',''ကြည့်မြင်တိုင်''),(''hlaingtharyaeast'',''လှိုင်သာယာ''),(''hlaingtharyawest'',''လှိုင်သာယာ''),(''hlaingtharyar(east)'',''လှိုင်သာယာ''),(''hlaingtharyar(west)'',''လှိုင်သာယာ''),(''နေပြည်တော်ကောင်စီနယ်မြေ'',''နေပြည်တော်''),'); execute d; end $patch$;